// Student card

// 1. Constant studentName - your name (a string in double quotes)

// 2. Constant courseName - "JavaScript"

// 3. Variable lessonsDone with let, initial value 0

// 4. Lesson done: assign lessonsDone the value 1

// 5. Print studentName, courseName and lessonsDone to the console

task.solution:
// Student card

const studentName = "Anna";
const courseName = "JavaScript";
let lessonsDone = 0;

// The first lesson is done
lessonsDone = 1;

console.log("Student:", studentName);
console.log("Course:", courseName);
console.log("Lessons done:", lessonsDone);

